561	
562	IRAM_ATTR void *riscv_dispatch_irq(uintreg_t mcause, uintreg_t *regs)
563	{
564	  /* Storm counter + latched storm mcause: plain RAM writes (never printed,
565	   * never block), so a reset + read tells us whether the CPU was spinning in
566	   * a dispatch storm and which trap source it was.  Addresses:
567	   * 0x5010ffe4 = storm counter (0x5010ffe0 = app marker, 0x5010fff0 = boot/
568	   * driver marker, 0x5010ffe8 = mcause latched when counter first exceeds
569	   * 50000; esp_bringup zeroes counter+latch after dumping, so the latch
570	   * always captures the PREVIOUS run's storm source and survives reset). */
571	  {
572	    volatile uint32_t *cnt = (volatile uint32_t *)0x5010ffe4;
573	    volatile uint32_t *lc = (volatile uint32_t *)0x5010ffe8;
574	    volatile uint32_t *irq_lc = (volatile uint32_t *)0x5010ffec;
575	    *cnt = *cnt + 1;
576	    if (*cnt > 1000 && *lc == 0)
577	      {
578	        *lc = (uint32_t)mcause;
579	        /* Resolve the storm cpuint back to an IRQ.  If the interrupting
580	         * peripheral was allocated via ESP-HAL's esp_intr_alloc_* (jpeg,
581	         * dma2d) instead of NuttX's esp_setup_irq, no handle was ever put
582	         * in g_handle_map, so this returns -1 (0xffffffff) and dispatch can
583	         * never service the interrupt -> level-triggered storm. */
584	        if ((RISCV_IRQ_BIT & mcause) != 0)
585	          {
586	            uint8_t cpuint = (uint8_t)((mcause & VECTORS_MCAUSE_REASON_MASK) -
587	                                       RV_EXTERNAL_INT_OFFSET);
588	            *irq_lc = (uint32_t)esp_cpuint_to_irq(cpuint, this_cpu());
589	          }
590	        else
591	          {
592	            *irq_lc = 0xffffffffu;
593	          }
594	      }
595	  }
596	
597	  /* Non-zeroed dispatch counter at 0x5010ff00.  Unlike the storm counter
598	   * (0x5010ffe4) this one is NOT cleared by esp_bringup after dumping, so a
599	   * boot M dump always reads the accumulated dispatch count.  The jpegnc app
600	   * records this value right before its final console flush (PR stage) into
