627	   *   head==tail (buffer empty)      -> stuck on nxmutex_lock(&xmit.lock)
628	   *   head/tail ~size apart (full)   -> stuck on nxsem_wait(&xmitsem) with
629	   *                                      IN_EMPTY masked and nobody draining
630	   * Slots:
631	   *   0x5010ffa0 = xmit.head<<16 | xmit.tail
632	   *   0x5010ffa4 = xmitsem.semcount
633	   *   0x5010ffa8 = USJ INT_ENA (IN_EMPTY = bit3, OUT_RECV_PKT = bit2)
634	   *   0x5010ffac = USJ INT_ST  (IN_EMPTY pending = bit3)
635	   *   0x5010ffb4 = USJ EP1_CONF (serial_in_ep_data_free = TX fifo has room) */
636	  {
637	    extern uart_dev_t g_uart_usbserial;
638	    volatile uint32_t *usj = (volatile uint32_t *)0x500D2000;
639	    uint16_t h = (uint16_t)g_uart_usbserial.xmit.head;
640	    uint16_t t = (uint16_t)g_uart_usbserial.xmit.tail;
641	    int16_t sc = *(volatile int16_t *)&g_uart_usbserial.xmitsem;
642	    *((volatile uint32_t *)0x5010ffa0) = ((uint32_t)h << 16) | t;
643	    *((volatile uint32_t *)0x5010ffa4) = (uint32_t)sc;
644	    *((volatile uint32_t *)0x5010ffa8) = usj[0x10 / 4];  /* USJ int_ena */
645	    *((volatile uint32_t *)0x5010ffac) = usj[0x0c / 4];  /* USJ int_st */
646	    *((volatile uint32_t *)0x5010ffb4) = usj[0x04 / 4];  /* USJ ep1_conf */
