659	      up_putc(hex[(mcause >> 20) & 0xF]); up_putc(hex[(mcause >> 16) & 0xF]);
660	      up_putc(hex[(mcause >> 12) & 0xF]); up_putc(hex[(mcause >> 8) & 0xF]);
661	      up_putc(hex[(mcause >> 4) & 0xF]);  up_putc(hex[mcause & 0xF]); up_putc(' ');
662	    }
