504	/****************************************************************************
505	 * Name: esp_teardown_irq
506	 *
507	 * Description:
508	 *   This function undoes the operations done by esp_setup_irq.
509	 *   It detaches an interrupt source from a CPU interrupt and frees the
510	 *   CPU interrupt.
511	 *
512	 * Input Parameters:
513	 *   source        - Interrupt source (see irq.h) to be detached from the
514	 *                   CPU interrupt.
515	 *   cpuint        - CPU interrupt from which the interrupt source will
516	 *                   be detached.
517	 *
518	 * Returned Value:
519	 *   None.
520	 *
521	 ****************************************************************************/
522	
523	void esp_teardown_irq(int source, int cpuint)
524	{
525	  esp_err_t ret;
526	  int cpu = this_cpu();
527	  int irq = ESP_SOURCE2IRQ(source);
528	  intr_handle_t intr_handle = esp_get_handle(cpu, irq);
529	
530	  UNUSED(cpuint);
531	
532	  if (intr_handle == IRQ_UNMAPPED)
533	    {
534	      irqwarn("No handle found for source %d\n", source);
535	      return;
536	    }
537	
538	  ret = esp_intr_free(intr_handle);
539	  if (ret != ESP_OK)
540	    {
541	      irqerr("Failed to free interrupt %d\n", source);
542	    }
543	
544	  esp_clear_handle(cpu, irq);
545	}
