1	/****************************************************************************
2	 * apps/examples/jpegenc/jpegenc_main.c
3	 *
4	 * Encode one RGB565 frame to JPEG using the ESP32-P4 hardware JPEG encoder
5	 * (/dev/video1, V4L2 M2M).
6	 *
7	 * Input:  /data/capture.rgb565  (1024x600 RGB565, from camcap)
8	 * Output: /data/capture.jpg
9	 *
10	 * SPDX-License-Identifier: Apache-2.0
11	 ****************************************************************************/
12	
13	#include <nuttx/config.h>
14	#include <stdio.h>
15	#include <stdlib.h>
16	#include <string.h>
17	#include <fcntl.h>
18	#include <unistd.h>
19	#include <errno.h>
20	#include <malloc.h>
21	#include <poll.h>
22	#include <sys/ioctl.h>
23	#include <sys/stat.h>
24	#include <sys/videoio.h>
25	
26	/* RAM debug markers (digits, distinct from arch markers W C i s b e P z c D
27	 * d m n o q E X).  dbg_mark_char() records to the app-only marker address
28	 * (0x5010ffe0) even when the USB console is wedged; the esp_bringup boot
29	 * dump reads it back after a warm reset.  Boot's dbg_putc() markers live at
30	 * 0x5010fff0 and would clobber this address, hence the separation.
31	 */
32	
33	extern void dbg_mark_char(int ch);
34	#define MARK(c) dbg_mark_char(c)
35	
36	/* Print the previous run's last RAM debug marker (survives warm reset). */
37	
38	#define PREV_MARK_ADDR ((volatile uint32_t *)0x5010ffe0)
39	
40	#define M2M_DEV     "/dev/video1"
41	#define IN_FILE     "/tmp/capture.rgb565"
42	#define OUT_FILE    "/tmp/capture.jpg"
43	#define W           1024
44	#define H           600
45	
46	/* RGB565 input frame size (2 bytes/pixel) */
47	#define OUT_SIZE    (W * H * 2)
48	/* JPEG output buffer: driver uses W*H for capture sizeimage, but allow slack */
49	#define CAP_SIZE    (W * H * 2)
50	
51	static int xioctl(int fd, int req, void *arg)
52	{
53	  int r;
54	  do { r = ioctl(fd, req, arg); } while (r == -1 && errno == EINTR);
55	  return r;
56	}
57	
58	int main(int argc, char *argv[])
59	{
60	  int fd = -1, infd = -1, outfd = -1;
61	  int ret = EXIT_FAILURE;
62	  struct v4l2_format fmt;
63	  struct v4l2_requestbuffers req;
64	  struct v4l2_buffer buf;
65	  void *inbuf = NULL;
66	  void *capbuf = NULL;
67	  enum v4l2_buf_type out_type = V4L2_BUF_TYPE_VIDEO_OUTPUT;
68	  enum v4l2_buf_type cap_type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
69	  size_t n;
70	
71	  uint32_t prev = *PREV_MARK_ADDR;
72	  printf("jpegenc: %dx%d RGB565 -> JPEG via %s\n", W, H, M2M_DEV);
73	  printf("  [prev marker] 0x%08x ('%c')\n", (unsigned int)prev,
74	         prev >= 0x20 && prev <= 0x7e ? (int)prev : '?');
75	  dbg_mark_char('#');            /* RAM-write self-test: expect 0x23 */
76	  printf("  [chk] 0x%02x\n", (int)(*PREV_MARK_ADDR));
77	  fflush(stdout);
78	  MARK('a');                     /* fflush done, about to allocate input */
79	
80	  /* Generate the RGB565 input frame in memory (skip file I/O for now) */
81	
82	  inbuf = memalign(64, OUT_SIZE);
83	  MARK('b');                     /* input memalign done */
84	  if (!inbuf)
85	    { printf("ERROR: memalign input\n"); goto out; }
86	  printf("  inbuf @ %p (%d bytes)\n", inbuf, OUT_SIZE);
87	  fflush(stdout);
88	
89	  {
90	    uint8_t *p = (uint8_t *)inbuf;
91	    size_t i;
92	    for (i = 0; i < OUT_SIZE; i++)
93	      {
94	        p[i] = (uint8_t)(i * 31 + (i >> 8));
95	      }
96	  }
97	  n = OUT_SIZE;
98	  MARK('f');                     /* input filled in memory */
99	  printf("  [marker@f] 0x%02x\n", (int)(*PREV_MARK_ADDR));
100	  fflush(stdout);
101	  *PREV_MARK_ADDR = 0xAA;        /* sentinel: survive warm reset */
102	  printf("  [sentinel] 0x%02x\n", (int)(*PREV_MARK_ADDR));
103	  fflush(stdout);
104	  printf("  generated %ld bytes in memory\n", (long)n);
105	  fflush(stdout);
106	
107	  /* Open M2M device */
108	
109	  MARK('0'); /* about to open M2M device */
110	  fd = open(M2M_DEV, O_RDWR, 0);
111	  if (fd < 0)
112	    { printf("ERROR: open %s: %d\n", M2M_DEV, errno); goto out; }
113	  MARK('1'); /* device open */
114	
115	  /* Set OUTPUT queue format: RGB565 */
116	
117	  memset(&fmt, 0, sizeof(fmt));
118	  fmt.type                = out_type;
119	  fmt.fmt.pix.width       = W;
120	  fmt.fmt.pix.height      = H;
121	  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;
122	  fmt.fmt.pix.field       = V4L2_FIELD_ANY;
123	  if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0)
124	    { printf("ERROR: OUTPUT S_FMT: %d\n", errno); goto out; }
125	  printf("  OUTPUT fmt: %ux%u sizeimage=%u\n",
126	         (unsigned int)fmt.fmt.pix.width, (unsigned int)fmt.fmt.pix.height,
127	         (unsigned int)fmt.fmt.pix.sizeimage);
128	  fflush(stdout);
129	  MARK('2'); /* output S_FMT ok */
130	
131	  /* Set CAPTURE queue format: JPEG */
132	
133	  memset(&fmt, 0, sizeof(fmt));
134	  fmt.type                = cap_type;
135	  fmt.fmt.pix.width       = W;
136	  fmt.fmt.pix.height      = H;
137	  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
138	  fmt.fmt.pix.field       = V4L2_FIELD_ANY;
139	  if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0)
140	    { printf("ERROR: CAPTURE S_FMT: %d\n", errno); goto out; }
141	  printf("  CAPTURE fmt: %ux%u sizeimage=%u\n",
142	         (unsigned int)fmt.fmt.pix.width, (unsigned int)fmt.fmt.pix.height,
143	         (unsigned int)fmt.fmt.pix.sizeimage);
144	  fflush(stdout);
145	  MARK('3'); /* capture S_FMT ok */
146	
147	  /* Request buffers on both queues (USERPTR) */
148	
149	  memset(&req, 0, sizeof(req));
150	  req.type   = out_type;
151	  req.memory = V4L2_MEMORY_USERPTR;
152	  req.count  = 2;
153	  if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0)
154	    { printf("ERROR: OUTPUT REQBUFS: %d\n", errno); goto out; }
155	
156	  memset(&req, 0, sizeof(req));
157	  req.type   = cap_type;
158	  req.memory = V4L2_MEMORY_USERPTR;
159	  req.count  = 2;
160	  if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0)
161	    { printf("ERROR: CAPTURE REQBUFS: %d\n", errno); goto out; }
162	  MARK('4'); /* reqbufs ok */
163	
164	  /* Allocate capture buffer and queue it on the CAPTURE queue */
165	
166	  capbuf = memalign(64, CAP_SIZE);
167	  if (!capbuf)
168	    { printf("ERROR: memalign capture\n"); goto out; }
169	
170	  memset(&buf, 0, sizeof(buf));
171	  buf.type      = cap_type;
172	  buf.memory    = V4L2_MEMORY_USERPTR;
173	  buf.index     = 0;
174	  buf.m.userptr = (unsigned long)capbuf;
175	  buf.length    = CAP_SIZE;
176	  if (xioctl(fd, VIDIOC_QBUF, &buf) < 0)
177	    { printf("ERROR: CAPTURE QBUF: %d\n", errno); goto out; }
178	  MARK('5'); /* capture qbuf ok */
179	
180	  /* Queue input frame on OUTPUT queue */
181	
182	  memset(&buf, 0, sizeof(buf));
183	  buf.type      = out_type;
184	  buf.memory    = V4L2_MEMORY_USERPTR;
185	  buf.index     = 0;
186	  buf.m.userptr = (unsigned long)inbuf;
187	  buf.length    = OUT_SIZE;
188	  buf.bytesused = OUT_SIZE;
189	  if (xioctl(fd, VIDIOC_QBUF, &buf) < 0)
190	    { printf("ERROR: OUTPUT QBUF: %d\n", errno); goto out; }
191	  MARK('6'); /* output qbuf ok */
192	
193	  /* Start both queues */
194	
195	  if (xioctl(fd, VIDIOC_STREAMON, &out_type) < 0)
196	    { printf("ERROR: OUTPUT STREAMON: %d\n", errno); goto out; }
197	  if (xioctl(fd, VIDIOC_STREAMON, &cap_type) < 0)
198	    { printf("ERROR: CAPTURE STREAMON: %d\n", errno); goto out; }
199	  MARK('7'); /* streaming */
200	  printf("  streaming...\n");
201	  fflush(stdout);
202	
203	  /* Wait for the encoded frame to be ready (DQBUF returns EAGAIN until then) */
204	
205	  {
206	    struct pollfd pfd;
207	    int pret;
208	
209	    pfd.fd     = fd;
210	    pfd.events = POLLIN;
211	    pfd.revents = 0;
212	    for (int tries = 0; tries < 50; tries++)
213	      {
214	        pret = poll(&pfd, 1, 100);
215	        if (pret < 0)
216	          { printf("ERROR: poll: %d\n", errno); goto out; }
217	        if (pret > 0 && (pfd.revents & POLLIN))
218	          {
219	            MARK('8'); /* poll ready */
220	            break;
221	          }
222	      }
223	
224	    if (pret <= 0 || !(pfd.revents & POLLIN))
225	      {
226	        printf("ERROR: timeout waiting for encoded frame\n");
227	        goto out;
228	      }
229	  }
230	
231	  /* Dequeue encoded JPEG */
232	
233	  memset(&buf, 0, sizeof(buf));
234	  buf.type   = cap_type;
235	  buf.memory = V4L2_MEMORY_USERPTR;
236	  if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0)
237	    { printf("ERROR: CAPTURE DQBUF: %d\n", errno); goto out; }
238	  printf("  encoded frame %u: %u bytes\n",
239	         (unsigned int)buf.index, (unsigned int)buf.bytesused);
240	  fflush(stdout);
241	  MARK('9'); /* encoded frame dequeued */
242	  /* Record the JPEG size at a dedicated RAM slot so the boot dump can verify
243	   * the encode actually produced data even when the USB console is lossy.
244	   * 0x5010ffc4 is not used by the boot M dump. */
245	  *((volatile uint32_t *)0x5010ffc4) = (uint32_t)buf.bytesused;
246	
247	  /* Write JPEG to file */
248	
249	  outfd = open(OUT_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
250	  if (outfd < 0)
251	    {
252	      *((volatile uint32_t *)0x5010ffc8) = (uint32_t)errno; /* open errno */
253	      printf("ERROR: open %s: %d\n", OUT_FILE, errno);
254	      goto out;
255	    }
256	  *((volatile uint32_t *)0x5010ffc8) = (uint32_t)outfd;      /* open ok: fd */
257	  MARK('>'); /* capture.jpg opened for write */
258	
259	  n = write(outfd, capbuf, buf.bytesused);
260	  *((volatile uint32_t *)0x5010ffcc) = (uint32_t)n;          /* write ret */
261	  if (n < 0)
262	    { printf("ERROR: write: %d\n", errno); goto out; }
263	  /* Record the first 4 bytes of the JPEG bitstream (should be FF D8 FF ...
264	   * for a valid SOI) at 0x5010ffb0 so the boot M dump can verify the magic
265	   * even if the console wedges on the final fflush below. */
266	  {
267	    FAR const uint8_t *jp = (FAR const uint8_t *)capbuf;
268	    *((volatile uint32_t *)0x5010ffb0) =
269	      (uint32_t)jp[0] | ((uint32_t)jp[1] << 8) |
270	      ((uint32_t)jp[2] << 16) | ((uint32_t)jp[3] << 24);
271	  }
272	  MARK('z'); /* JPEG written to /tmp/capture.jpg (before console flush) */
273	  /* Record the boot's non-zeroed dispatch counter (0x5010ff00) at the last
274	   * pre-flush marker so the post-hang M dump can tell whether the tick kept
275	   * firing while the final printf was wedged.  Delta vs 0x5010ff00 at dump =
276	   * dispatches during hang + boot. */
277	  *((volatile uint32_t *)0x5010ff08) = *((volatile uint32_t *)0x5010ff00);
278	
279	  /* Pinpoint where the console flush wedges.  0x5010ff9c stage marker:
