static int esp_interrupt(int irq, void *context, void *arg)
{
  struct uart_dev_s *dev = (struct uart_dev_s *)arg;
  uint32_t int_status = usb_serial_jtag_ll_get_intsts_mask();

  /* Send buffer has room and can accept new data. */

  if ((int_status & USB_SERIAL_JTAG_INTR_SERIAL_IN_EMPTY) != 0)
    {
      usb_serial_jtag_ll_clr_intsts_mask(
        USB_SERIAL_JTAG_INTR_SERIAL_IN_EMPTY);
      uart_xmitchars(dev);

      /* If uart_xmitchars() just drained the xmit buffer empty, its final
       * esp_txint(false) may have deferred the ZLP flush because the TX FIFO
       * was still busy transmitting the last bytes (SERIAL_IN_EP_DATA_FREE
       * is latched low until the USB engine reads the FIFO).  This IN_EMPTY
       * is then the signal that the FIFO has freed.  Send the zero-length
       * packet that terminates the USB IN transaction so the host releases
       * any full 64-byte packet it is holding (otherwise the host's read()
       * never returns and the console "wedges"), then disarm the interrupt. */

      if (dev->xmit.head == dev->xmit.tail &&
          usb_serial_jtag_ll_txfifo_writable())
        {
          usb_serial_jtag_ll_txfifo_flush();   /* zero-length packet */
          usb_serial_jtag_ll_disable_intr_mask(
            USB_SERIAL_JTAG_INTR_SERIAL_IN_EMPTY);
