static void esp_send(struct uart_dev_s *dev, int ch)
{
  volatile int tries = 0;
  uint8_t buf[1] = {
    (uint8_t)ch
  };
  int n;

  /* Record the last char pushed through the console driver's TX interrupt
   * path (uart_xmitchars -> esp_send) at a fixed RAM marker.  dbg_putc
   * writes DBG_MARK_ADDR directly and never comes through here, so this
   * address distinguishes a K-flood flowing through the xmit buffer from a
   * polled-output flood (which would hit esp_usbserial_write / 0x5010ffd4). */

  *((volatile uint32_t *)0x5010ffd0) = (uint32_t)(uint8_t)ch;

  /* uart_xmitchars() gates this call on uart_txready(), but a flush in
   * flight latches SERIAL_IN_EP_DATA_FREE low between that check and the
   * write, so write_txfifo can still refuse the byte.  Wait (bounded) for
   * the FIFO to accept it so it is never silently lost; the count below is
   * a diagnostic backstop that should stay at zero. */

  while (!usb_serial_jtag_ll_txfifo_writable())
    {
      if (++tries > 3000)
        {
          *((volatile uint32_t *)0x5010ff58) += 1;         /* drop counter */
          *((volatile uint32_t *)0x5010ff5c) = (uint32_t)(uint8_t)ch |
            (usb_serial_jtag_ll_get_intsts_mask() << 8);   /* char + int_st */
          return;
        }
    }

  /* Write the character to the buffer and flush it out. */

  n = usb_serial_jtag_ll_write_txfifo(buf, sizeof(buf));
  usb_serial_jtag_ll_txfifo_flush();

  /* DIAGNOSTIC backstop: count + record any byte that still could not be
   * placed (the wedge dump can confirm the mechanism). */

  if (n != 1)
    {
      *((volatile uint32_t *)0x5010ff58) += 1;             /* drop counter */
      *((volatile uint32_t *)0x5010ff5c) = (uint32_t)(uint8_t)ch |
        (usb_serial_jtag_ll_get_intsts_mask() << 8);       /* char + int_st */
    }
}

