static void esp_txint(struct uart_dev_s *dev, bool enable)
{
  if (enable)
    {
      usb_serial_jtag_ll_ena_intr_mask(
        USB_SERIAL_JTAG_INTR_SERIAL_IN_EMPTY);
    }
  else
    {
      /* The xmit buffer is drained.  The USB-Serial-JTAG TX FIFO latches
       * SERIAL_IN_EP_DATA_FREE low after a flush until the USB engine reads
       * the FIFO, so a flush issued right now may be a no-op while the host
       * is left holding a full 64-byte packet as an incomplete USB IN
       * transaction -- its read() never returns and the console wedges.
       * Send the zero-length packet that terminates the transaction when
       * the FIFO is free; otherwise keep IN_EMPTY armed so esp_interrupt()
       * completes the flush as soon as the FIFO frees. */

      if (usb_serial_jtag_ll_txfifo_writable())
        {
          usb_serial_jtag_ll_txfifo_flush();   /* zero-length packet */
          usb_serial_jtag_ll_disable_intr_mask(
            USB_SERIAL_JTAG_INTR_SERIAL_IN_EMPTY);
        }
      /* else: FIFO busy flushing the last bytes -- leave IN_EMPTY enabled;
       * esp_interrupt() sends the ZLP when the FIFO frees. */
    }
}

