91	                uint32_t sent_size = usb_serial_jtag_ll_write_txfifo(queued_buf, queued_size);
92	                usb_serial_jtag_ll_txfifo_flush();
93	
94	                // Check if we were able to send everything.
95	                if (sent_size < queued_size) {
96	                    // Not all bytes could be sent at once; stash the unwritten bytes in a buffer
97	                    // This will happen if e.g. the rom output functions manage to sneak a few bytes into the
98	                    // TX FIFO before this interrupt triggers. Note stash_size will not larger than
99	                    // USB_SER_JTAG_ENDP_SIZE because queued_size is obtained from xRingbufferReceiveUpToFromISR.
100	                    size_t stash_size = queued_size - sent_size;
101	                    memcpy(p_usb_serial_jtag_obj->tx_stash_buf, &queued_buf[sent_size], stash_size);
102	                    p_usb_serial_jtag_obj->tx_stash_cnt = stash_size;
103	                } else {
104	                    p_usb_serial_jtag_obj->tx_stash_cnt = 0;
105	                }
106	                // Return the buffer if we got it from the ring buffer.
107	                if (queued_buf != p_usb_serial_jtag_obj->tx_stash_buf) {
108	                    vRingbufferReturnItemFromISR(p_usb_serial_jtag_obj->tx_ring_buf, queued_buf, &xTaskWoken);
109	
110	                    // We just moved items out of the TX ring buffer, the driver is considered write ready, since
111	                    // the TX ring buffer is assured to be not full.
112	                    if (p_usb_serial_jtag_obj->usj_select_notif_callback) {
113	                        p_usb_serial_jtag_obj->usj_select_notif_callback(USJ_SELECT_WRITE_NOTIF, &xTaskWoken);
114	                    }
115	                }
116	            } else {
117	                // No data to send.
118	                // The last transmit may have sent a full EP worth of data. The host will interpret
119	                // this as a transaction that hasn't finished yet and keep the data in its internal
120	                // buffers rather than releasing it to the program listening on the CDC serial port.
121	                // We need to flush again in order to send a 0-byte packet that ends the transaction.
122	                usb_serial_jtag_ll_txfifo_flush();
123	
124	                // We will also disable the interrupt as for now there's no need to handle the
125	                // TX interrupt again. We'll re-enable this externally if we need data sent.
126	                usb_serial_jtag_ll_disable_intr_mask(USB_SERIAL_JTAG_INTR_SERIAL_IN_EMPTY);
127	
128	                // Technically something could have been pushed into the ringbuffer between us checking
129	                // here and us disabling the interrupt. That would mean that data would not be
130	                // transmitted anymore. Check for that case.
131	                UBaseType_t bytes_waiting;
132	                vRingbufferGetInfo(p_usb_serial_jtag_obj->tx_ring_buf, NULL, NULL, NULL, NULL, &bytes_waiting);
133	                if (bytes_waiting) {
134	                    // Uh-oh, it happened. Re-enable interrupts so we can process the data the next run.
135	                    usb_serial_jtag_ll_ena_intr_mask(USB_SERIAL_JTAG_INTR_SERIAL_IN_EMPTY);
136	                } else {
137	                    //Nope, still nothing. Mark tx as idle.
138	                    xSemaphoreGiveFromISR(p_usb_serial_jtag_obj->tx_idle_sem, &xTaskWoken);
139	                }
140	            }
141	        }
142	    }
143	
144	    if (usbjtag_intr_status & USB_SERIAL_JTAG_INTR_SERIAL_OUT_RECV_PKT) {
145	        // Acknowledge interrupt
146	        usb_serial_jtag_ll_clr_intsts_mask(USB_SERIAL_JTAG_INTR_SERIAL_OUT_RECV_PKT);
147	        // Read RX FIFO and send available data to ringbuffer.
148	        uint8_t buf[USB_SER_JTAG_RX_MAX_SIZE];
149	        uint32_t rx_fifo_len = usb_serial_jtag_ll_read_rxfifo(buf, USB_SER_JTAG_RX_MAX_SIZE);
150	        xRingbufferSendFromISR(p_usb_serial_jtag_obj->rx_ring_buf, buf, rx_fifo_len, &xTaskWoken);
151	
152	        if (p_usb_serial_jtag_obj->usj_select_notif_callback) {
153	            p_usb_serial_jtag_obj->usj_select_notif_callback(USJ_SELECT_READ_NOTIF, &xTaskWoken);
154	        }
155	    }
156	
157	    if (xTaskWoken == pdTRUE) {
158	        portYIELD_FROM_ISR();
159	    }
160	}
