178	    p_usb_serial_jtag_obj->rx_ring_buf = xRingbufferCreate(usb_serial_jtag_config->rx_buffer_size, RINGBUF_TYPE_BYTEBUF);
179	    if (p_usb_serial_jtag_obj->rx_ring_buf == NULL) {
180	        ESP_LOGE(USB_SERIAL_JTAG_TAG, "ringbuffer create error");
