185	    p_usb_serial_jtag_obj->tx_ring_buf = xRingbufferCreate(usb_serial_jtag_config->tx_buffer_size, RINGBUF_TYPE_BYTEBUF);
186	    if (p_usb_serial_jtag_obj->tx_ring_buf == NULL) {
