199	    p_usb_serial_jtag_obj->tx_idle_sem = xSemaphoreCreateBinary();
200	    if (p_usb_serial_jtag_obj->tx_idle_sem == NULL) {
201	        ESP_LOGE(USB_SERIAL_JTAG_TAG, "tx_idle_sem create error");
202	        err = ESP_ERR_NO_MEM;
203	        goto _exit;
204	    }
205	
206	    // Enable USB-Serial-JTAG peripheral module clock
207	    USJ_RCC_ATOMIC() {
208	        usb_serial_jtag_ll_enable_bus_clock(true);
209	    }
210	
211	    // Configure PHY
212	#if USB_SERIAL_JTAG_LL_EXT_PHY_SUPPORTED
213	    usb_serial_jtag_ll_phy_enable_external(false);  // Use internal PHY
214	    usb_serial_jtag_ll_phy_enable_pad(true);        // Enable USB PHY pads
215	#else // USB_SERIAL_JTAG_LL_EXT_PHY_SUPPORTED
