224	    // We only enable the RX interrupt; we'll enable the TX one when we actually
225	    // have anything to send.
226	    usb_serial_jtag_ll_ena_intr_mask(USB_SERIAL_JTAG_INTR_SERIAL_OUT_RECV_PKT);
227	
228	    //Assume tx is idle; if any we have nothing in the ringbuffer so this is probably true.
229	    xSemaphoreGive(p_usb_serial_jtag_obj->tx_idle_sem);
230	
231	    err = esp_intr_alloc(ETS_USB_SERIAL_JTAG_INTR_SOURCE, 0, usb_serial_jtag_isr_handler_default, NULL, &p_usb_serial_jtag_obj->intr_handle);
232	    if (err != ESP_OK) {
233	        goto _exit;
234	    }
235	    return ESP_OK;
236	
237	_exit:
238	    usb_serial_jtag_driver_uninstall();
239	    return err;

250	
251	    // Receive new data from ISR
252	    data = (uint8_t*) xRingbufferReceiveUpTo(p_usb_serial_jtag_obj->rx_ring_buf, &data_read_len, (TickType_t) ticks_to_wait, length);
253	    if (data == NULL) {
254	        // If there is no data received from ringbuffer, return 0 directly.
255	        return 0;
256	    }
257	
258	    memcpy((uint8_t*)buf, data, data_read_len);
259	    vRingbufferReturnItem(p_usb_serial_jtag_obj->rx_ring_buf, data);
260	    data = NULL;
261	
262	    return data_read_len;
