265	int usb_serial_jtag_write_bytes(const void* src, size_t size, uint32_t ticks_to_wait)
266	{
267	    ESP_RETURN_ON_FALSE(src && size, 0, USB_SERIAL_JTAG_TAG, "invalid buffer or size");
268	    ESP_RETURN_ON_FALSE(p_usb_serial_jtag_obj != NULL, 0, USB_SERIAL_JTAG_TAG, "driver is not initialized yet");
269	
270	    //This will block when something else is waiting in wait_tx_done, making sure we don't add data to the ringbuffer.
271	    //Note that the ringbuffer itself is thread-safe, so this is only needed to handle wait_tx_done.
272	    BaseType_t result = xSemaphoreTake(p_usb_serial_jtag_obj->tx_mux, ticks_to_wait);
273	    if (result == pdFALSE) {
274	        return 0;
275	    }
276	
277	    //Mark TX as not idle so flush function knows to wait. Note we don't care if it was already not idle, so no
278	    //timeout and we don't check if this succeeds; we just want to make sure the semaphore is taken.
279	    xSemaphoreTake(p_usb_serial_jtag_obj->tx_idle_sem, 0);
280	
281	    result = xRingbufferSend(p_usb_serial_jtag_obj->tx_ring_buf, (void*)src, size, ticks_to_wait);
282	    // Re-enable the TX interrupt. If this was disabled, this will immediately trigger the ISR
283	    // and send the things we just put in the ringbuffer. Note that even though this is a
284	    // read-modify-write operation on the interrupt enable register that could happen at the
285	    // same point the ISR does a read-modify-write to disable the interrupt,
286	    usb_serial_jtag_ll_ena_intr_mask(USB_SERIAL_JTAG_INTR_SERIAL_IN_EMPTY);
287	    xSemaphoreGive(p_usb_serial_jtag_obj->tx_mux);
288	    return (result == pdFALSE) ? 0 : size;
289	}
