291	esp_err_t usb_serial_jtag_wait_tx_done(uint32_t ticks_to_wait)
292	{
293	    int r;
294	    TimeOut_t timeout;
295	    vTaskSetTimeOutState(&timeout);
296	    // Make sure write_bytes blocks so nothing is added to the ringbuffer.
297	    // Note that this can time out (e.g. blocked ringbuffer while writing)
298	    r = xSemaphoreTake(p_usb_serial_jtag_obj->tx_mux, ticks_to_wait);
299	    if (r) {
300	        // Adjust timeout to compensate for the time we waited for tx_mux. Note xTaskCheckForTimeOut
301	        // changes ticks_to_wait accordingly.
302	        if (xTaskCheckForTimeOut(&timeout, &ticks_to_wait)) {
303	            // if this triggers, we timed out: we got tx_mux at the exact time of the timeout? Probably
304	            // never happens, but handle correctly anyway.
305	            ticks_to_wait = 0;
306	        }
307	        // Check if we're idle or wait until we are (or time out)
308	        r = xSemaphoreTake(p_usb_serial_jtag_obj->tx_idle_sem, ticks_to_wait);
309	        if (r) {
310	            // We could take the semaphore, meaning tx is done now. Immediately give it again so
311	            // the next run of usb_serial_jtag_wait_tx_done also succeeds.
312	            xSemaphoreGive(p_usb_serial_jtag_obj->tx_idle_sem);
313	        }
314	        // Re-allow writes.
315	        xSemaphoreGive(p_usb_serial_jtag_obj->tx_mux);
316	    }
317	    return r ? ESP_OK : ESP_ERR_TIMEOUT;
318	}
