321	//work on a half-initialized driver as well.
322	esp_err_t usb_serial_jtag_driver_uninstall(void)
323	{
324	    if (p_usb_serial_jtag_obj == NULL) {
325	        ESP_LOGE(USB_SERIAL_JTAG_TAG, "uninstall without install called");
326	        return ESP_OK;
327	    }
328	
329	    /* Don't disable the module clock and usb_pad_enable here since the USJ stdout might still depends on it. */
330	
331	    usb_serial_jtag_ll_disable_intr_mask(USB_SERIAL_JTAG_INTR_SERIAL_IN_EMPTY | USB_SERIAL_JTAG_INTR_SERIAL_OUT_RECV_PKT);
332	    if (p_usb_serial_jtag_obj->intr_handle) {
333	        esp_intr_free(p_usb_serial_jtag_obj->intr_handle);
334	    }
335	
336	    if (p_usb_serial_jtag_obj->rx_ring_buf) {
337	        vRingbufferDelete(p_usb_serial_jtag_obj->rx_ring_buf);
338	        p_usb_serial_jtag_obj->rx_ring_buf = NULL;
339	    }
340	    if (p_usb_serial_jtag_obj->tx_ring_buf) {
341	        vRingbufferDelete(p_usb_serial_jtag_obj->tx_ring_buf);
342	        p_usb_serial_jtag_obj->tx_ring_buf = NULL;
343	    }
344	    if (p_usb_serial_jtag_obj->tx_idle_sem) {
345	        vSemaphoreDelete(p_usb_serial_jtag_obj->tx_idle_sem);
346	        p_usb_serial_jtag_obj->tx_idle_sem  = NULL;
347	    }
348	    if (p_usb_serial_jtag_obj->tx_mux) {
349	        vSemaphoreDelete(p_usb_serial_jtag_obj->tx_mux);
350	        p_usb_serial_jtag_obj->tx_mux  = NULL;
351	    }
352	    heap_caps_free(p_usb_serial_jtag_obj);
353	    p_usb_serial_jtag_obj = NULL;
354	    return ESP_OK;
355	}
