proc create_esp_jtag { } {
    global _CHIPNAME _CPUTAPID _HP_TAPNUM _LP_TAPNUM _LP_TAPID _LP_TAP_FIRST

    set tapnum 0

    # New chips with distinct HP/LP TAP IDs
    if {[info exists _LP_TAPID]} {

        if {![info exists _LP_TAP_FIRST]} {
            set _LP_TAP_FIRST 0
        }

        if {$_LP_TAP_FIRST} {
            # LP first
            for {set i 0} {$i < $_LP_TAPNUM} {incr i} {
                jtag newtap $_CHIPNAME tap$tapnum -irlen 5 -expected-id $_LP_TAPID
                incr tapnum
            }
            for {set i 0} {$i < $_HP_TAPNUM} {incr i} {
                jtag newtap $_CHIPNAME tap$tapnum -irlen 5 -expected-id $_CPUTAPID
                incr tapnum
            }
        } else {
            # Legacy/default order: HP first
            for {set i 0} {$i < $_HP_TAPNUM} {incr i} {
                jtag newtap $_CHIPNAME tap$tapnum -irlen 5 -expected-id $_CPUTAPID
                incr tapnum
            }
            for {set i 0} {$i < $_LP_TAPNUM} {incr i} {
                jtag newtap $_CHIPNAME tap$tapnum -irlen 5 -expected-id $_LP_TAPID
                incr tapnum
            }
        }
        return
    }

    # Legacy chips: all taps use the same TAP ID
    for {set i 0} {$i < ($_HP_TAPNUM + $_LP_TAPNUM)} {incr i} {
        jtag newtap $_CHIPNAME tap$tapnum -irlen 5 -expected-id $_CPUTAPID
        incr tapnum
    }
}

