91	/****************************************************************************
92	 * Name: jpeg_encode_one
93	 *
94	 * Description:
95	 *   Pull one RGB565 frame from the OUTPUT queue, encode it with the JPEG
96	 *   HAL, and push the resulting bitstream into the CAPTURE queue.
97	 *   Safe to call from either *_available() callback (the v4l2_m2m core
98	 *   calls these after each QBUF on the respective queue); no-ops when a
99	 *   frame or a capture buffer is missing.
100	 *
101	 ****************************************************************************/
102	
103	static int jpeg_encode_one(FAR void *priv)
104	{
105	  struct esp_jpeg_dev_s *d = priv;
106	  FAR struct v4l2_buffer *in;
107	  FAR struct v4l2_buffer *cap;
108	  jpeg_encode_cfg_t cfg;
109	  uint32_t out_sz = 0;
110	  esp_err_t err;
111	
112	  if (d->engine == NULL)
113	    {
114	      return 0;
115	    }
116	
117	  in = codec_output_get_buf(d->cookie);
118	  if (in == NULL)
119	    {
120	      return 0;
121	    }
122	
123	  dbg_putc('p');               /* jpeg_encode_one: about to get capture buf */
124	  cap = codec_capture_get_buf(d->cookie);
125	  if (cap == NULL)
126	    {
127	      codec_output_put_buf(d->cookie, in);
128	      return 0;
129	    }
130	
131	  memset(&cfg, 0, sizeof(cfg));
132	  cfg.width         = d->out_fmt.fmt.pix.width;
133	  cfg.height        = d->out_fmt.fmt.pix.height;
134	  cfg.src_type      = JPEG_ENCODE_IN_FORMAT_RGB565;
135	  cfg.sub_sample    = JPEG_DOWN_SAMPLING_YUV420;
136	  cfg.image_quality = JPEG_QUALITY;
137	
138	  dbg_putc('q');               /* about to call jpeg_encoder_process */
139	  err = jpeg_encoder_process(d->engine, &cfg,
140	                             (FAR const uint8_t *)in->m.vaddr,
141	                             in->length,
142	                             (FAR uint8_t *)cap->m.vaddr,
143	                             cap->length,
144	                             &out_sz);
145	  dbg_putc('r');               /* jpeg_encoder_process returned */
146	  if (err != ESP_OK)
147	    {
148	      vwarn("jpeg encode failed: %d\n", err);
149	      cap->bytesused = 0;
150	      codec_capture_put_buf(d->cookie, cap);
151	      codec_output_put_buf(d->cookie, in);
152	      return 0;
153	    }
154	
155	  vinfo("encoded %u x %u RGB565 -> %u bytes JPEG\n",
156	        cfg.width, cfg.height, (unsigned int)out_sz);
157	  cap->bytesused = out_sz;
158	  d->encoded = out_sz;
159	  codec_capture_put_buf(d->cookie, cap);
160	  codec_output_put_buf(d->cookie, in);
161	  return 0;
162	}
