164	static int jpeg_open(FAR void *cookie, FAR void **priv)
165	{
166	  struct esp_jpeg_dev_s *d;
167	  dbg_putc('V');               /* jpeg_open entered */
168	  d = kmm_zalloc(sizeof(*d));
169	  jpeg_encode_engine_cfg_t ecfg;
170	  esp_err_t err;
171	
172	  if (d == NULL)
173	    {
174	      return -ENOMEM;
175	    }
176	
177	  d->cookie = cookie;
178	  d->out_fmt.type = V4L2_BUF_TYPE_VIDEO_OUTPUT;
179	  d->out_fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;
180	  d->out_fmt.fmt.pix.width  = JPEG_DEF_WIDTH;
181	  d->out_fmt.fmt.pix.height = JPEG_DEF_HEIGHT;
182	  d->out_fmt.fmt.pix.sizeimage = JPEG_DEF_WIDTH * JPEG_DEF_HEIGHT * 2;
183	  d->cap_fmt = d->out_fmt;
184	  d->cap_fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
185	
186	  /* Create the ESP-HAL JPEG encoder engine.  One engine per open file;
187	   * the HAL reference-counts the underlying codec handle internally. */
188	
189	  memset(&ecfg, 0, sizeof(ecfg));
190	  ecfg.intr_priority = 0;   /* driver picks a default */
191	  ecfg.timeout_ms    = 1000; /* 1 s is well above a 1024x600 encode */
192	
193	  dbg_putc('W');               /* about to call jpeg_new_encoder_engine */
194	  /* ARM the dispatch storm latch right here: zero the counter/latch so the
195	   * latch captures the FIRST trap of THIS engine's storm (not boot leftovers).
196	   * 0x5010ffe4=cnt, 0x5010ffe8=mcause latch, 0x5010ffec=resolved irq. */
197	  *((volatile uint32_t *)0x5010ffe4) = 0;
198	  *((volatile uint32_t *)0x5010ffe8) = 0;
199	  *((volatile uint32_t *)0x5010ffec) = 0;
200	  *((volatile uint32_t *)0x5010fe40) = 0;   /* mcause ring head */
201	  err = jpeg_new_encoder_engine(&ecfg, &d->engine);
202	  dbg_putc('X');               /* jpeg_new_encoder_engine returned */
203	  /* TEST: determine whether the wedge is in printf/fflush (UART TX IRQ) or
204	   * elsewhere.  P1 = before printf, P2 = printf returned, P3 = fflush done,
205	   * P4 = after everything.  All via polled dbg_putc (no TX IRQ needed). */
206	  dbg_putc('P'); dbg_putc('1'); dbg_putc('='); dbg_putc('\r'); dbg_putc('\n');
207	  printf("jpeg_open: jpeg_new_encoder_engine -> %d\n", (int)err);
208	  dbg_putc('P'); dbg_putc('2'); dbg_putc('='); dbg_putc('\r'); dbg_putc('\n');
209	  fflush(stdout);
210	  dbg_putc('P'); dbg_putc('3'); dbg_putc('='); dbg_putc('\r'); dbg_putc('\n');
211	  if (err != ESP_OK)
212	    {
213	      verr("jpeg_new_encoder_engine failed: %d\n", err);
214	      kmm_free(d);
215	      return -ENODEV;
216	    }
217	
218	  *priv = d;
219	  return OK;
220	}
